from __future__ import division

import logging
import math
import re
import time

from taf.ue.tm500.rci.interface import rci
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferVerificationFailure
from ute_ue.utils.param_checker import tput_user_value2normalized

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

rci = rci()


class ViaviDataTransfer(LteDataTransfer):
    def __init__(self, alias, dt_definition, configuration, sender_reciever_details, logger_name='ta_ue',
                 rci_timeout=None):
        """
        Basic initialization.

        :param name alias: Alias to be assigned to DataTransfer object
        :param name dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param dict configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param float timeout: timeout in seconds for RCI commands (if used)
        """
        # TODO: add suport for bidirectional traffic
        # Bidirectional traffic was added in ute_ue 5.7.0 (TAUE-996)
        if dt_definition.direction == "simultaneous_ul_dl":
            raise NotImplementedError("bidirectional traffic is not supported yet")

        super(ViaviDataTransfer, self).__init__(alias, dt_definition, configuration, logger_name)
        self.data_transfer = configuration
        default_parallel_iperf_streams = self.get_number_parallel_iperf_streams(self.data_transfer.get(
            'parallel_iperf_streams', 1))
        self.direction = dt_definition.direction
        self.duration = dt_definition.duration
        self.throughput = dt_definition.throughput
        self.protocol = dt_definition.protocol
        self.epc_pppd = sender_reciever_details
        self.name = alias
        self.dt_server = self.data_transfer['server']
        self.dt_epc = self.data_transfer['epc']
        self.ue_ssh = self.epc_pppd['pppd_ssh']
        network_host_ssh = self.epc_pppd['epc_ssh']
        self.pppoe_ssh = self.ue_ssh
        self.rci_timeout = rci_timeout

        if self.direction == 'dl':
            self.sender_ssh = network_host_ssh
            self.receiver_ssh = self.ue_ssh
        else:  # 'ul'
            self.sender_ssh = self.ue_ssh
            self.receiver_ssh = network_host_ssh

        self.logger.warning("Current viavi plugin only use the value in existed scenario file, "
                            "most parameters passed by start traffic are not used .")
        self.number_iperf_streams = self.get_number_parallel_iperf_streams(dt_definition.protocol_details.get(
            'parallel_iperf_streams', default_parallel_iperf_streams))

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        data_transfer_size = int(self.throughput)
        iperf_stream_size = str(int(math.ceil(data_transfer_size / self.number_iperf_streams))) + 'K'
        ue_iperf_ip = self.data_transfer['pppoe_ue_ip']
        epc_iperf_ip = self.dt_epc['iperf_interface_ip']
        protocol = '' if self.protocol.lower() != 'udp' else '-u'
        if self.direction == 'dl':
            self.target_ip = ue_iperf_ip
            self.source_ip = epc_iperf_ip
        else:  # 'ul'
            self.target_ip = epc_iperf_ip
            self.source_ip = ue_iperf_ip

        server_command = "iperf -s {protocol} -p {port} -t {time} -i 1 -B {interface_ip} > {path}/{file}.txt & echo $! > {path}/{file}_pid.txt"
        server_command = server_command.format(protocol=protocol,
                                               port=self.data_transfer['port'],
                                               time=self.duration,
                                               interface_ip=self.target_ip,
                                               path=self.data_transfer.get('iperf_output_path', '/tmp'),
                                               file=self.name)
        client_command = ("iperf -c {target_ip} {protocol} -p {port} -l 1024 -i 20 -b {size} -t {time} "
                          "-P {parallel_iperf_streams} -B {interface_ip}  > /dev/null 2>&1 & echo $! > {path}/{file}_pid.txt")
        client_command = client_command.format(target_ip=self.target_ip,
                                               protocol=protocol,
                                               port=self.data_transfer['port'],
                                               size=iperf_stream_size,
                                               time=self.duration,
                                               parallel_iperf_streams=self.number_iperf_streams,
                                               interface_ip=self.source_ip,
                                               path=self.data_transfer.get('iperf_output_path', '/tmp'),
                                               file=self.name)

        logger.info("Starting {}.".format("uplink" if self.direction == 'ul'
                                          else "downlink"))
        # During the start of data transfer removes the server output file if it is existing
        self._remove_server_output_file()
        # set timeout - used in await data transfer finish. To wait untill data transfer finish.
        self.timeout = time.time() + self.duration + 10
        self.receiver_ssh.send_command(command=server_command)
        logger.debug("Running iperf command on {ip}: {command}".format(ip=self.target_ip, command=server_command))
        self.sender_ssh.send_command(command=client_command)
        logger.debug("Running iperf command on {ip}: {command}".format(ip=self.source_ip, command=client_command))

        self.receiver_pid = self._get_iperf_process_pid(self.receiver_ssh)
        self.sender_pid = self._get_iperf_process_pid(self.sender_ssh)

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        self._kill_pid(self.receiver_ssh, self.receiver_pid)
        self._kill_pid(self.sender_ssh, self.sender_pid)

    def verify_average_throughput(self, tput_min, tput_max=None):
        """
        Verify if running throughput is in desired range: tput_min <-> tput_max
        If tput_max=None: Verify if running throughput is above desired threshold: tput_min

        :param tput_min: lower threshold for desired average data transfer throughput in string format. e.g. '1M'
        :param tput_max: upper threshold for desired average data transfer throughput in string format. e.g. '4M'
        :return: None
        :raises DataTransferVerificationFailure: if verification fails
        """

        file = "{path}/{file}.txt".format(path=self.data_transfer.get('iperf_output_path', '/tmp'), file=self.name)
        self.receiver_ssh.send_command("cat " + file)
        self.server_output = self.receiver_ssh.read_output()
        logger.debug("server output=%r" % self.server_output)
        average_throughput = self.get_average_throughput()
        normalized_tput_min = tput_user_value2normalized(tput_min)

        if average_throughput == -1:
            msg = 'Packets are not acknowledged from the server'

            raise DataTransferVerificationFailure(msg)

        if average_throughput < normalized_tput_min:
            msg = ("Expected tput_min={normalized_tput_min} [kbits/s] \n"
                   "Actual average tput={average_throughput} [kbits/sec]")
            msg = msg.format(normalized_tput_min=normalized_tput_min,
                             average_throughput=average_throughput)

            raise DataTransferVerificationFailure(msg)

        if tput_max and average_throughput > tput_user_value2normalized(tput_max):
            msg = ("Expected tput_min={normalized_tput_min} [kbits/s] \n"
                   "Expected tput_max={normalized_tput_max} [kbits/s] \n"
                   "Actual average tput={average_throughput} [kbits/sec]")

            msg = msg.format(normalized_tput_min=normalized_tput_min,
                             normalized_tput_max=tput_user_value2normalized(tput_max),
                             average_throughput=average_throughput)

            raise DataTransferVerificationFailure(msg)

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        self.sender_ssh.send_command(" ps  -p " + self.sender_pid + " | wc -l")
        command = self.sender_ssh.read_output()
        return True if command != "2" else False

    def get_average_throughput(self):
        """
        Abstract method for getting average throughput of data transfer.

        Average throughput is measured from 'dt.start()' to 'dt.stop()' after data transfer is already finished or
        has been stopped

        :return: value of Average throughput in unit: Kbits/sec
        """
        try:
            throughput = re.findall(r"[\d\\.]+\s+[GgMmKk]bits/sec+", self.server_output)[-1]
            return tput_user_value2normalized(throughput)

        except IndexError:
            return -1

    def verify_average_throughput_with_deviation(self, tput, deviation):
        """
        Verify if average throughput is in desired range: tput-(tput*deviation) <-> tput+(tput*deviation)

        :param tput: desired average data transfer throughput in string format. e.g. '1M'
        :param deviation: acceptable deviation (expressed in percentages) from desired data transfer throughput. e.g '5%'
        :return: None
        :raises DataTransferVerificationFailure: if verification fails
        """
        file = "{path}/{file}.txt".format(path=self.data_transfer.get('iperf_output_path', '/tmp'), file=self.name)
        self.receiver_ssh.send_command("cat " + file)
        self.server_output = self.receiver_ssh.read_output()
        logger.debug("server output=%r" % self.server_output)
        average_throughput = self.get_average_throughput()
        deviation_as_float = self._parse_deviation(deviation)
        normalized_tput = tput_user_value2normalized(tput)
        min_threshold = normalized_tput - (normalized_tput * deviation_as_float)
        max_threshold = normalized_tput + (normalized_tput * deviation_as_float)

        if average_throughput == -1:
            msg = 'Packets are not acknowledged from the server'

            raise DataTransferVerificationFailure(msg)

        if average_throughput < min_threshold or average_throughput > max_threshold:
            msg = ("\nBased on values provided: "
                   "tput={normalized_tput} [kbits/s], "
                   "deviation={dev}"
                   "Expected tput range: "
                   "min={min_threshold} [kbits/sec] <-> max={max_threshold} [kbits/sec]"
                   "Actual average tput={actual} [kbits/sec]")

            msg = msg.format(normalized_tput=normalized_tput,
                             dev=deviation,
                             min_threshold=min_threshold,
                             max_threshold=max_threshold,
                             actual=average_throughput)
            raise DataTransferVerificationFailure(msg)

    def await_finish(self):
        """
        Wait until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.

        No action if given data transfer is already finished.
        """
        while time.time() < self.timeout:
            if not self.is_running():
                logger.debug("iperf process execution stopped.")
                break
            time.sleep(self.duration / 10)  # to reduce number of iterations

        if time.time() >= self.timeout:
            logger.debug("timeout happened waiting for iperf process.")
            self.stop()

    def check_data_transfer_is_alive(self):
        """
        Check if data transfer between client and server is progressing.

        :return: True or False
        """
        return self.is_running()

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ta_abstract_lib_core.exceptions.UnknownAlias`: if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ta_abstract_lib_core.exceptions.WrongAlias`: if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ta_ue.exceptions.UeProcedureError`: If reset data transfer statistics failed
        """
        raise NotImplementedError

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        raise NotImplementedError

    def get_number_parallel_iperf_streams(self, dt_iperf_streams):
        """
        Calculate the number of parallel iperf streams to run.
        possible values for parallel_iperf_streams in ue_config.yml : { positive int , 'auto'}
        If 'auto' is given, then the maximum possible number of simultaneous threads available to the host CPU is
        considered .
        Default value is 1
        :param dt_iperf_streams: value of 'parallel_iperf_streams' from ue_config.yml
        :return:
        """
        if (dt_iperf_streams):
            try:
                if int(dt_iperf_streams) <= 0:
                    logger.warning("The number of parallel iperf streams to run should be either a positive integer or "
                                   "the string \"auto\"")
                    iperf_streams = 1
                else:
                    iperf_streams = dt_iperf_streams
            except ValueError:
                if dt_iperf_streams.lower() == "auto":
                    nproc_output = self.sender_ssh.execute("nproc;sleep 1")
                    iperf_streams = ''.join(filter(lambda i: i.isdigit(), nproc_output))
        return int(iperf_streams)

    def _get_iperf_process_pid(self, ssh):
        pid = ssh.execute("cat {path}/{file}_pid.txt ; rm {path}/{file}_pid.txt".format(path=self.data_transfer.get('iperf_output_path', '/tmp'),
                          file=self.name))
        logger.debug("iperf_pid {} ".format(pid))
        return ''.join(filter(lambda i: i.isdigit(), pid))

    def _kill_pid(self, ssh, pid):
        ssh.execute('kill -SIGINT {}'.format(pid))

    def _remove_server_output_file(self):
        file = "{path}/{file}.txt".format(path=self.data_transfer.get('iperf_output_path', '/tmp'), file=self.name)
        self.receiver_ssh.send_command("rm -f " + file)
        file = "{path}/{file}_pid.txt".format(path=self.data_transfer.get('iperf_output_path', '/tmp'), file=self.name)
        self.receiver_ssh.send_command("rm -f " + file)
